function run(T,F){let n=0;const eq=(a,b)=>{if(a!==b)throw Error('Expected '+b+' got '+a);n++};const throws=fn=>{let x=false;try{fn()}catch{x=true}eq(x,true)};const rows=[{id:'1',date:'2026-01-01',trade:'Trucking',type:'Income',category:'Linehaul',cents:100000},{id:'2',date:'2026-01-02',trade:'Trucking',type:'Expense',category:'Diesel',cents:20000},{id:'3',date:'2026-01-02',trade:'Trucking',type:'Transfer',category:'Escrow contribution',cents:10000},{id:'4',date:'2026-01-02',trade:'Trucking',type:'Transfer',category:'Principal',classification:'principal',cents:5000},{id:'5',date:'2026-01-02',trade:'Trucking',type:'Transfer',category:'Sales tax collected',cents:1000}];const before=JSON.stringify(rows),r=T.taxReport(rows,2026,{'expense|Diesel':{code:'9',percent:100,confirmed:true}});eq(r.net,80000);eq(r.cash,66000);eq(r.taxNet,80000);eq(r.groups['9'],20000);eq(T.taxReport(rows,2026).taxNet,100000);eq(T.taxReport(rows,2026).pending['expense|Diesel'],20000);const a={...T.assumption(2026),federalRate:'10',stateRate:'5',reserveRate:'25'};const e=T.estimate(a,10000000);eq(e.se,1412955);eq(e.fedIncome,929352);eq(e.stateTax,500000);eq(e.annual,2842307);eq(e.reserveTarget,2500000);eq(T.estimate({...a,ssWages:'184500'},10000000).se,267815);eq(T.estimate(a,1000).se,0);throws(()=>T.estimate(T.assumption(2026),100000));const q=T.quarterly(a,e,[]);eq(q.reduce((s,x)=>s+x.target,0),e.federalDue);eq(q[3].due,'2027-01-15');const p=T.taxPayment({year:2026,quarter:1,authority:'Federal',date:'2026-04-15',amount:'100',ref:'IRS1'},[],'p');eq(T.quarterly(a,e,[p])[0].recorded,10000);throws(()=>T.taxPayment({...p,amount:'100'},[p],'p2'));
const d=T.blank();d.envelopes.push(T.envelope(d,{name:'Taxes',direction:'contribution',date:'2026-01-01',amount:'100'},'e1'));eq(T.envelopeBalance(d,'Taxes'),10000);throws(()=>T.envelope(d,{name:'Taxes',direction:'withdrawal',date:'2026-01-02',amount:'101'},'e2'));d.envelopes.push(T.envelope(d,{name:'Taxes',direction:'withdrawal',date:'2026-01-02',amount:'25'},'e2'));eq(T.envelopeBalance(d,'Taxes'),7500);
const m=T.mileage({date:'2026-06-30',vehicle:'Car',purpose:'Service',miles:'100',method:'standard',eligible:true},'m');eq(T.mileageEstimate(m),7250);eq(T.mileageEstimate({...m,date:'2026-07-01'}),7600);eq(T.mileageEstimate({...m,method:'actual'}),null);eq(T.travel({depart:'2026-01-01',return:'2026-01-03',home:'0',partial:'75',rate:'80',deduct:'80',note:'Eligible travel'},'t').estimated,16000);
eq(T.asset({name:'Equipment',acquired:'2026-01-01',cost:'1000',businessUse:'80',prior:'100',current:'200',year:2026},'a').basis,80000);
const v={job:'truck',loaded:2400,deadhead:600,mpg:7.5,diesel:5.3,linehaul:1.45,fsc:.56,discount:0,dispatch:0,reserve:.263,fixed:'915',cashCosts:'0',otherCost:'0',goal:'1000',taxRate:25,owner:'100',weeks:52};const b=T.forecast(v);eq(b.revenue,482400);eq(b.expenses,303500);eq(b.profit,178900);eq(b.reserve,78900);eq(b.cash,100000);eq(T.forecast({...v,diesel:6.3}).profit,b.profit-40000);eq(T.forecast({...v,equipment:'5000'}).annual.cash,b.annual.cash-500000);eq(T.forecast({...v,equipment:'5000'}).annual.profit,b.annual.profit);eq(b.annual.profit,b.profit*52);eq(b.monthly.at(-1).ending,b.annual.cash);eq(T.forecast({...v,growth:10}).years[1].revenue,Math.round(b.annual.revenue*1.1));const mech=T.forecast({job:'mechanic',hours:20,hourly:100,partsCost:'100',markup:30,laborCost:'20',fixed:'500',weeks:52});eq(mech.revenue,213000);eq(mech.expenses,100000);eq(mech.profit,113000);eq(T.forecast({job:'mechanic',hours:20,hourly:110,partsCost:'100',markup:50,laborCost:'20',fixed:'500',weeks:52}).profit,135000);const slow=T.forecast({...v,weeks:40});eq(slow.annual.expenses,91500*52+212000*40);eq(slow.annual.cash,slow.annual.profit-78900*40);eq(slow.monthly.at(-1).ending,slow.annual.cash);eq(slow.years[0].profit,slow.annual.profit);eq(T.yearMapping({mapping:{2026:{'expense|Diesel':{code:'9',percent:100,confirmed:true}}}},2025)['expense|Diesel'],undefined);eq(T.estimate({...a,futureProfit:'-1000'},10000000).profit,9900000);eq(T.progress(rows,{goals:{},taxPlanning:{annualGoal:'12000'}},'2026-01-02')[1].target,100000);eq(JSON.stringify(rows),before);return n}
